_scheduleNotification() {
  lazy.clearTimeout(this._showNotificationTimer);
  this._showNotificationTimer = null;

  if (!this._jsonFile.data.notifications.length) {
    return;
  }

  const now = Date.now();
  const [nextNotification] = this._jsonFile.data.notifications
    .map(n => Date.parse(n.start_at))
    .filter(n => n > now)
    .sort((a, b) => a - b);
  if (!nextNotification) {
    return;
  }

  this._showNotificationTimer = lazy.setTimeout(() => {
    this._showNotificationTimer = null;
    this._updateNotificationManager();
  }, nextNotification - Date.now());

_updateNotificationManager() {
  // Wait for the debounce before updating notifications.
  if (this._localeChangeDebounce) {
    return;
  }
  this._scheduleNotification();
  this.notificationManager.updatedNotifications(this.getNotifications());
},

isActiveNotification(notification, seed, interactedWithIds) {
  if (interactedWithIds.includes(notification.id)) {
    return false;
  }
  // Bypass after the interaction check, so we don't keep showing the same
  // notification. Especially relevant with _tab variants that would else just
  // keep opening tabs (until we hit the limiter in the NotificationManager).
  if (lazy.bypassFiltering) {
    return true;
  }

  // First, check if this notification is allowed by policy.
  if (
    /* eslint-disable-next-line mozilla/valid-lazy */
    !lazy._enabled ||
    lazy[`_${notification.type.split("_", 1)[0]}Enabled`] === false
  ) {
    return false;
  }

  const now = Date.now();
  const parsedEnd = Date.parse(notification.end_at);
  const parsedStart = Date.parse(notification.start_at);
  if (
    Number.isNaN(parsedEnd) ||
    Number.isNaN(parsedStart) ||
    parsedEnd < now ||
    parsedStart > now
  ) {
    return false;
  }
